def calc(expr):
    pos = 0

    def skip_spaces():
        nonlocal pos
        while pos < len(expr) and expr[pos] == ' ':
            pos += 1

    def parse_number():
        nonlocal pos
        skip_spaces()
        num = 0
        while pos < len(expr) and expr[pos].isdigit():
            num = num * 10 + int(expr[pos])
            pos += 1
        return num

    def parse_unary():
        nonlocal pos
        skip_spaces()
        sign = 1
        while pos < len(expr) and expr[pos] == '-':
            sign *= -1
            pos += 1
            skip_spaces()

        if pos < len(expr) and expr[pos] == '(':
            pos += 1
            result = parse_add_sub()
            skip_spaces()
            if pos < len(expr) and expr[pos] == ')':
                pos += 1
            return sign * result
        else:
            return sign * parse_number()

    def parse_mul_div():
        nonlocal pos
        left = parse_unary()

        while True:
            skip_spaces()
            if pos < len(expr) and expr[pos] in '*/':
                op = expr[pos]
                pos += 1
                right = parse_unary()
                if op == '*':
                    left = left * right
                else:  # op == '/'
                    left = int(left / right)
            else:
                break

        return left

    def parse_add_sub():
        nonlocal pos
        left = parse_mul_div()

        while True:
            skip_spaces()
            if pos < len(expr) and expr[pos] in '+-':
                op = expr[pos]
                pos += 1
                right = parse_mul_div()
                if op == '+':
                    left = left + right
                else:  # op == '-'
                    left = left - right
            else:
                break

        return left

    return parse_add_sub()

